async function confirmFrameworkInit(framework) {
    closeFrameworkSelectModal();
    if (!activeProject) return;

    try {
        const response = await fetch(`/api/project/${encodeURIComponent(activeProject)}/init-framework`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ framework: framework })
        });

        const data = await response.json();
        if (response.ok) {
            alert(`Initialized ${framework} successfully! Generated files:\n` + data.files.join("\n"));
            if (typeof loadExplorerRoot === 'function') {
                loadExplorerRoot();
            }
        } else {
            alert(data.error || `Failed to initialize ${framework}`);
        }
    } catch (err) {
        console.error(`Error initializing ${framework}:`, err);
        alert(`Error initializing ${framework}`);
    }
}

