let stashPanelOpen = false;

function toggleStashPanel() {
    const panel = document.getElementById('stash-panel');
    const arrow = document.getElementById('stash-panel-arrow');
    const refreshBtn = document.getElementById('stash-refresh-btn');
    stashPanelOpen = !stashPanelOpen;
    if (stashPanelOpen) {
        panel.style.display = 'block';
        arrow.style.transform = 'rotate(90deg)';
        refreshBtn.style.display = 'inline-block';
        loadStashes();
    } else {
        panel.style.display = 'none';
        arrow.style.transform = 'rotate(0deg)';
        refreshBtn.style.display = 'none';
    }
}

async function loadStashes() {
    if (!activeProject) return;
    const listEl = document.getElementById('stash-list');
    const badge = document.getElementById('stash-count-badge');
    const statusEl = document.getElementById('stash-status-msg');
    if (!listEl) return;
    listEl.innerHTML = '<div style="padding:10px 14px; color:var(--text-secondary); font-size:0.8rem;">Loading...</div>';
    if (statusEl) statusEl.innerText = '';
    try {
        const res = await fetch(`/api/project/${encodeURIComponent(activeProject)}/git/stash/list`);
        const data = await res.json();
        if (!res.ok) {
            listEl.innerHTML = `<div style="padding:10px 14px; color:#ef4444; font-size:0.8rem;">${data.error || 'Failed to load stashes'}</div>`;
            return;
        }
        const stashes = data.stashes || [];
        if (badge) {
            if (stashes.length > 0) {
                badge.textContent = stashes.length;
                badge.style.display = 'inline-block';
            } else {
                badge.style.display = 'none';
            }
        }
        if (stashes.length === 0) {
            listEl.innerHTML = '<div style="padding:10px 14px; color:var(--text-secondary); font-size:0.8rem; font-style:italic;">No stashes found.</div>';
            return;
        }
        listEl.innerHTML = stashes.map(s => `
            <div style="padding:7px 12px; border-bottom:1px solid var(--border-color); display:flex; align-items:center; gap:8px; transition:background-color 0.15s;" onmouseenter="this.style.backgroundColor='var(--bg-sidebar)'" onmouseleave="this.style.backgroundColor='transparent'">
                <span style="font-family:'Fira Code',monospace; font-size:0.68rem; color:#fb923c; min-width:72px; flex-shrink:0;">${s.ref}</span>
                <div style="flex:1; min-width:0;">
                    <div style="font-size:0.78rem; color:var(--text-primary); white-space:nowrap; overflow:hidden; text-overflow:ellipsis;" title="${s.message}">${s.message}</div>
                    <div style="font-size:0.68rem; color:var(--text-muted); margin-top:1px;">${s.when}</div>
                </div>
                <div style="display:flex; gap:4px; flex-shrink:0;">
                    <button onclick="gitStashApply('${s.ref}')" title="Apply — restore stash, keep it in list" style="background:none; border:1px solid #38bdf8; color:#38bdf8; cursor:pointer; font-size:0.68rem; padding:2px 7px; border-radius:4px; transition:all 0.2s; white-space:nowrap;" onmouseenter="this.style.backgroundColor='rgba(56,189,248,0.12)'" onmouseleave="this.style.backgroundColor='transparent'">Apply</button>
                    <button onclick="gitStashPop('${s.ref}')" title="Pop — restore stash and remove from list" style="background:none; border:1px solid #34d399; color:#34d399; cursor:pointer; font-size:0.68rem; padding:2px 7px; border-radius:4px; transition:all 0.2s; white-space:nowrap;" onmouseenter="this.style.backgroundColor='rgba(52,211,153,0.12)'" onmouseleave="this.style.backgroundColor='transparent'">Pop</button>
                    <button onclick="gitStashDrop('${s.ref}')" title="Drop — delete this stash permanently" style="background:none; border:1px solid #f87171; color:#f87171; cursor:pointer; font-size:0.68rem; padding:2px 7px; border-radius:4px; transition:all 0.2s; white-space:nowrap;" onmouseenter="this.style.backgroundColor='rgba(248,113,113,0.12)'" onmouseleave="this.style.backgroundColor='transparent'">Drop</button>
                </div>
            </div>
        `).join('');
    } catch (e) {
        listEl.innerHTML = `<div style="padding:10px 14px; color:#ef4444; font-size:0.8rem;">Error loading stashes.</div>`;
    }
}

async function gitStashPush() {
    if (!activeProject) return;
    const msgInput = document.getElementById('stash-message-input');
    const statusEl = document.getElementById('stash-status-msg');
    const btn = document.getElementById('stash-push-btn');
    const message = msgInput ? msgInput.value.trim() : '';
    if (btn) { btn.disabled = true; btn.style.opacity = '0.6'; }
    if (statusEl) statusEl.innerText = '';
    try {
        const res = await fetch(`/api/project/${encodeURIComponent(activeProject)}/git/stash/push`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ message })
        });
        const data = await res.json();
        if (res.ok && data.success) {
            if (msgInput) msgInput.value = '';
            if (statusEl) { statusEl.style.color = '#34d399'; statusEl.innerText = '✓ ' + (data.output || 'Stashed!'); }
            loadStashes();
        } else {
            if (statusEl) { statusEl.style.color = '#ef4444'; statusEl.innerText = data.error || 'Stash failed'; }
        }
    } catch (e) {
        if (statusEl) { statusEl.style.color = '#ef4444'; statusEl.innerText = e.message; }
    } finally {
        if (btn) { btn.disabled = false; btn.style.opacity = '1'; }
    }
}

async function gitStashApply(ref) {
    if (!activeProject) return;
    const statusEl = document.getElementById('stash-status-msg');
    if (statusEl) statusEl.innerText = '';
    try {
        const res = await fetch(`/api/project/${encodeURIComponent(activeProject)}/git/stash/apply`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ ref })
        });
        const data = await res.json();
        if (res.ok && data.success) {
            if (statusEl) { statusEl.style.color = '#34d399'; statusEl.innerText = '✓ Applied ' + ref; }
            // Refresh the changed files list so staged files update
            setTimeout(() => openGitCommitModal(), 800);
        } else {
            if (statusEl) { statusEl.style.color = '#ef4444'; statusEl.innerText = data.error || 'Apply failed'; }
        }
    } catch (e) {
        if (statusEl) { statusEl.style.color = '#ef4444'; statusEl.innerText = e.message; }
    }
}

async function gitStashPop(ref) {
    if (!activeProject) return;
    const statusEl = document.getElementById('stash-status-msg');
    if (statusEl) statusEl.innerText = '';
    try {
        const res = await fetch(`/api/project/${encodeURIComponent(activeProject)}/git/stash/pop`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ ref })
        });
        const data = await res.json();
        if (res.ok && data.success) {
            if (statusEl) { statusEl.style.color = '#34d399'; statusEl.innerText = '✓ Popped ' + ref; }
            setTimeout(() => openGitCommitModal(), 800);
        } else {
            if (statusEl) { statusEl.style.color = '#ef4444'; statusEl.innerText = data.error || 'Pop failed'; }
        }
    } catch (e) {
        if (statusEl) { statusEl.style.color = '#ef4444'; statusEl.innerText = e.message; }
    }
}

async function gitStashDrop(ref) {
    if (!activeProject) return;
    if (!confirm(`Drop ${ref}? This permanently deletes the stash.`)) return;
    const statusEl = document.getElementById('stash-status-msg');
    if (statusEl) statusEl.innerText = '';
    try {
        const res = await fetch(`/api/project/${encodeURIComponent(activeProject)}/git/stash/drop`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ ref })
        });
        const data = await res.json();
        if (res.ok && data.success) {
            if (statusEl) { statusEl.style.color = '#34d399'; statusEl.innerText = '✓ Dropped ' + ref; }
            loadStashes();
        } else {
            if (statusEl) { statusEl.style.color = '#ef4444'; statusEl.innerText = data.error || 'Drop failed'; }
        }
    } catch (e) {
        if (statusEl) { statusEl.style.color = '#ef4444'; statusEl.innerText = e.message; }
    }
}

