        closeAllStatusPopovers();
        pop.classList.add('show');
        const aiBtn = document.getElementById('ai-copilot-btn');
        if (aiBtn) aiBtn.classList.add('active');
        const savedProvider = localStorage.getItem('ai-provider') || 'gemini';
        const providerSelect = document.getElementById('ai-provider-select');
        if (providerSelect) providerSelect.value = savedProvider;
        if (typeof handleAIProviderChange === 'function') handleAIProviderChange();
        if (typeof refreshAIProviderLabels === 'function') refreshAIProviderLabels();
        if (typeof renderAIChatHistory === 'function') renderAIChatHistory();
        if (typeof _popoverOutside === 'function') _popoverOutside('ai-copilot-popover', 'ai-copilot-btn', closeAICopilotPopover);
    }
    // Fill prompt and focus
    const promptIn = document.getElementById('ai-prompt-input');
